Object.assign(ar,{'Your everyday coffee.':'قهوتك اليومية.','Current order':'الطلب الحالي','Items':'الأصناف'});
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=n=>`${n.toFixed(2)} KD`,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let currentLanguage=localStorage.getItem('sukun-language')==='ar'?'ar':'en';
const originalText=new WeakMap(),originalAttributes=new WeakMap();
function arabicPhrase(value){if(ar[value])return ar[value];if(value.includes(' · '))return value.split(' · ').map(arabicPhrase).join(' · ');let match=value.match(/^(.*?)(\d+(?:\.\d+)?) KD$/);if(match)return `${arabicPhrase(match[1])}${match[2]} د.ك`;match=value.match(/^(\d+) items?$/);if(match)return `${match[1]} ${Number(match[1])===1?'صنف':'أصناف'}`;match=value.match(/^(\d+) active$/);if(match)return `${match[1]} قيد التنفيذ`;match=value.match(/^(\d+) completed$/);if(match)return `${match[1]} مكتمل`;match=value.match(/^Step (\d+) of (\d+)$/);if(match)return `الخطوة ${match[1]} من ${match[2]}`;match=value.match(/^(.+) added$/);if(match)return `تمت إضافة ${arabicPhrase(match[1])}`;if(value.startsWith('Save '))return `وفّر ${arabicPhrase(value.slice(5))}`;if(value.startsWith('Signed in as '))return `تم تسجيل الدخول باسم ${value.slice(13)}`;if(value.startsWith('Welcome, '))return `أهلاً، ${value.slice(9)}`;return value.replace(/\bKD\b/g,'د.ك')}
function localizedText(source){const leading=source.match(/^\s*/)[0],trailing=source.match(/\s*$/)[0],value=source.trim();return value?`${leading}${arabicPhrase(value)}${trailing}`:source}
function localizeTree(root=document.body){const textNodes=[];if(root.nodeType===Node.TEXT_NODE)textNodes.push(root);else{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))textNodes.push(node)}textNodes.forEach(node=>{if(!originalText.has(node))originalText.set(node,node.nodeValue);const source=originalText.get(node);node.nodeValue=currentLanguage==='ar'?localizedText(source):source});const elements=root.nodeType===Node.ELEMENT_NODE?[root,...root.querySelectorAll('[placeholder],[aria-label],[title]')]:[];elements.forEach(element=>['placeholder','aria-label','title'].forEach(attribute=>{if(!element.hasAttribute(attribute))return;let saved=originalAttributes.get(element);if(!saved){saved={};originalAttributes.set(element,saved)}if(!(attribute in saved))saved[attribute]=element.getAttribute(attribute);element.setAttribute(attribute,currentLanguage==='ar'?arabicPhrase(saved[attribute]):saved[attribute])}))}
function setLanguage(language){currentLanguage=language==='ar'?'ar':'en';localStorage.setItem('sukun-language',currentLanguage);document.documentElement.lang=currentLanguage;document.documentElement.dir=currentLanguage==='ar'?'rtl':'ltr';localizeTree(document.body);$$('[data-language-toggle]').forEach(button=>{button.textContent=currentLanguage==='ar'?'English':'العربية';button.setAttribute('aria-label',currentLanguage==='ar'?'التبديل إلى الإنجليزية':'Switch to Arabic')});document.title=currentLanguage==='ar'?'سكون كافيه — لوقتك الهادئ':'Sukun Coffee — Made for your pause'}
let cart=JSON.parse(localStorage.getItem('sukun-cart')||'[]'),orders=JSON.parse(localStorage.getItem('sukun-orders')||'[]'),storedAccount=JSON.parse(localStorage.getItem('sukun-account')||'null'),customer=localStorage.getItem('sukun-signed-in')==='true'?storedAccount:null;
let activeCategory='All',vegOnly=false,searchTerm='',activeProduct=null,activeCombo=null,productQty=1,comboQty=1,checkoutStep=1,authMode='signin',pendingCheckoutBranch=null,lastOrder=null;
if(customer&&orders.some(order=>!order.customerEmail)){orders=orders.map(order=>order.customerEmail?order:{...order,customerEmail:customer.email.toLowerCase()});localStorage.setItem('sukun-orders',JSON.stringify(orders))}
const total=()=>cart.reduce((sum,item)=>sum+item.unitPrice*item.qty,0);
function photo(p,className='product-photo',label=p.name){return `<div class="${className}" role="img" aria-label="${esc(label)}" style="background-image:url('${p.image}');background-size:${p.size||'cover'};background-position:${p.pos||'center'}"></div>`}
function nutrition(p){return `<div class="product-nutrition" aria-label="Approximate nutrition per serving"><b>${p.calories} kcal</b><span>Protein ${p.nutrition.protein}g · Carbs ${p.nutrition.carbs}g · Fat ${p.nutrition.fat}g</span></div>`}
function productCard(p){return `<article class="product-card" tabindex="0" role="button" data-product="${p.id}" aria-label="View ${p.name}, ${money(p.price)}"><div class="product-image">${photo(p)}</div><button class="quick-add" data-quick-add="${p.id}" aria-label="Quick add ${p.name}">+</button><div class="product-info"><div class="product-top"><h3>${p.name}</h3><span class="product-price">${money(p.price)}</span></div><p>${p.desc}</p>${nutrition(p)}${p.tags.length?`<div class="product-tags">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div>`:''}</div></article>`}
function renderFeatured(){$('#featured-products').innerHTML=products.filter(p=>p.featured).map(productCard).join('')}
function renderCombos(){$('#combo-grid').innerHTML=combos.map(c=>`<article class="combo-card"><div class="combo-visual"><img class="combo-photo" src="${c.image}" alt="${esc(c.desc)} together on a café table" loading="lazy"></div><div class="combo-body"><span class="combo-badge">${c.badge}</span><h3>${c.name}</h3><p>${c.desc}</p><div class="combo-price"><strong>${money(c.price)}</strong><s>${money(c.regular)}</s><span>Save ${money(c.regular-c.price)}</span></div><button class="button button-dark" data-add-combo="${c.id}">Customize combo</button></div></article>`).join('')}
function renderLocations(){$('#location-preview').innerHTML=locations.map(l=>`<article class="location-mini"><div><div><h3>${l.name.replace('Sukun ','')}</h3><p>${l.area}</p></div><span class="pickup-available">Pickup</span></div><a href="#locations">Hours & directions</a></article>`).join('');$('#locations-grid').innerHTML=locations.map(l=>`<article class="location-card"><div class="location-card-image"><img src="${l.image}" alt="Warm, naturally lit interior at ${l.name}" loading="lazy"></div><div class="location-card-body"><h2>${l.name}</h2><p class="location-area">${l.area}</p><div class="location-details"><div><span>Open daily</span><b>${l.hours}</b></div><div><span>Pickup</span><b class="pickup-available">Available · ${l.ready}</b></div></div><div class="location-actions"><a class="button button-outline" href="${l.map}" target="_blank" rel="noopener">Directions ↗</a><button class="button button-dark" data-order-branch="${l.id}">Order here</button></div></div></article>`).join('')}
function renderFilters(){const select=$('#category-filter');select.innerHTML=categories.map(c=>`<option value="${c}" ${c===activeCategory?'selected':''}>${c==='All'?'All categories':c}</option>`).join('')}
function updateVegToggle(){const button=$('#veg-filter');button.setAttribute('aria-pressed',String(vegOnly));$('#veg-filter-state').textContent=vegOnly?'On · Vegetarian + vegan':'Off'}
function renderMenu(){const visible=products.filter(p=>(activeCategory==='All'||p.category===activeCategory)&&(!vegOnly||p.tags.some(t=>/vegetarian|vegan/i.test(t)))&&(`${p.name} ${p.desc} ${p.category}`.toLowerCase().includes(searchTerm.toLowerCase())));$('#menu-grid').innerHTML=visible.map(productCard).join('');$('#menu-empty').hidden=visible.length!==0;$('#menu-grid').hidden=visible.length===0;$('#results-label').textContent=`${activeCategory==='All'?'All day menu':activeCategory} · ${visible.length} item${visible.length===1?'':'s'}`;renderFilters();updateVegToggle()}
function closeMobileMenu(){const menu=$('.mobile-menu');if(menu)menu.open=false}
function route(){const hash=(location.hash||'#home').slice(1),[key,anchor]=hash.split('?'),view=$(`[data-view="${key}"]`)||$('[data-view="home"]'),navKey=anchor==='events'?'events':key;$$('.view').forEach(v=>v.classList.toggle('is-active',v===view));$$('[data-nav]').forEach(a=>a.classList.toggle('is-active',a.dataset.nav===navKey));closeMobileMenu();window.scrollTo({top:0,behavior:'auto'});if(anchor)requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView({behavior:'smooth',block:'start'}));closePanels(false)}
function updateCart(){localStorage.setItem('sukun-cart',JSON.stringify(cart));const count=cart.reduce((sum,item)=>sum+item.qty,0);$$('[data-cart-count]').forEach(el=>{el.textContent=count;el.hidden=Boolean(el.closest('.header-order'))&&count===0});if($('#cart-drawer').classList.contains('is-open'))renderCart()}
function syncAccountUI(){$$('[data-account-label]').forEach(el=>el.textContent=customer?'My account':'Sign in');$$('.account-avatar').forEach(el=>el.textContent=customer?customer.name.charAt(0).toUpperCase():'○')}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('is-visible');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('is-visible'),2600)}
function openPanel(id){$('#overlay').hidden=false;requestAnimationFrame(()=>$(id).classList.add('is-open'));$(id).setAttribute('aria-hidden','false');document.body.classList.add('is-locked');setTimeout(()=>$(id).querySelector('button,input')?.focus(),100)}
function closePanels(unlock=true){$$('.drawer').forEach(d=>{d.classList.remove('is-open');d.setAttribute('aria-hidden','true')});$('#overlay').hidden=true;if(unlock)document.body.classList.remove('is-locked')}
function options(name,items){return `<div class="segmented">${items.map((x,i)=>`<div class="choice"><input type="radio" id="${name}-${i}" name="${name}" value="${x.label}" data-add="${x.add||0}" ${i===0?'checked':''}><label for="${name}-${i}">${x.label}${x.add?`<small>+${money(x.add)}</small>`:''}</label></div>`).join('')}</div>`}
function drinkOptions(p){const size=p.id==='espresso'?[{label:'Double'},{label:'Quad',add:.6}]:[{label:'Regular'},{label:'Large',add:.35}],serveDefault=fixedServe[p.id]||(p.category==='Iced Coffee'?'Iced':'Hot'),serve=fixedServe[p.id]?`<input type="hidden" name="serve" value="${serveDefault}" data-config>`:`<div class="option-group"><div class="option-label"><h3>Serve</h3><small>Choose one</small></div>${options('serve',[{label:serveDefault},{label:serveDefault==='Iced'?'Hot':'Iced'}])}</div>`,milk=milkDrinkIds.has(p.id)?`<div class="option-group"><div class="option-label"><h3>Milk</h3><small>Choose one</small></div>${options('milk',[{label:'Whole milk'},{label:'Oat',add:.25},{label:'Almond',add:.25},{label:'Coconut',add:.25}])}</div>`:'',sweetness=sweetDrinkIds.has(p.id)?`<div class="option-group"><div class="option-label"><h3>Sweetness</h3><small>Choose one</small></div>${options('sweetness',[{label:'Regular'},{label:'Less sweet'},{label:'No sweetener'}])}</div>`:'',coffeeExtra=coffeeDrinkIds.has(p.id)?`<div class="check-row"><label><input type="checkbox" name="extra" value="Extra espresso shot" data-add="0.45"> Extra espresso shot</label><span>+0.45 KD</span></div>`:'',flavourExtra=milkDrinkIds.has(p.id)?`<div class="check-row"><label><input type="checkbox" name="extra" value="Vanilla syrup" data-add="0.25"> Vanilla syrup</label><span>+0.25 KD</span></div>`:p.id==='mint-tea'?`<div class="check-row"><label><input type="checkbox" name="extra" value="Honey" data-add="0.20"> Honey</label><span>+0.20 KD</span></div>`:'',extras=coffeeExtra||flavourExtra?`<div class="option-group"><div class="option-label"><h3>Extras</h3><small>Optional</small></div><div class="check-list">${coffeeExtra}${flavourExtra}</div></div>`:'';return `<div class="option-group"><div class="option-label"><h3>Size</h3><small>Choose one</small></div>${options('size',size)}</div>${serve}${milk}${sweetness}${extras}`}
function foodOptions(p){return `<div class="option-group"><div class="option-label"><h3>Preparation</h3><small>Choose one</small></div>${options('preparation',[{label:'Warm'},{label:'As is'}])}</div>${p.category==='Sandwiches'?`<div class="option-group"><div class="option-label"><h3>Extras</h3><small>Optional</small></div><div class="check-list"><div class="check-row"><label><input type="checkbox" name="extra" value="Extra halloumi" data-add=".55"> Extra halloumi</label><span>+0.55 KD</span></div></div></div>`:''}`}
function allergenNotice(p){const allergens=allergenMap[p.id]||[];return `<div class="allergen-note"><b>Allergen information</b><span>${allergens.length?`Contains ${allergens.join(', ')}.`:'No major allergens in the standard recipe.'}</span><small>Prepared where milk, gluten, eggs, sesame and nuts are handled. Milk alternatives share equipment.</small></div>`}
function restoreProductOptions(item){if(item.choices){$$('#product-drawer input').forEach(input=>{const saved=item.choices[input.name]||[];if(input.type==='radio'||input.type==='checkbox')input.checked=saved.includes(input.value)});return}const groups=[...new Set($$('#product-drawer input[type=radio]').map(input=>input.name))];groups.forEach((name,index)=>{const input=$$('#product-drawer input[type=radio]').find(option=>option.name===name&&option.value===item.config[index]);if(input)input.checked=true});$$('#product-drawer input[type=checkbox]').forEach(input=>input.checked=item.config.includes(input.value))}
function openProduct(id,editIndex=null){activeProduct=products.find(p=>p.id===id);activeCombo=null;productQty=editIndex!==null?cart[editIndex].qty:1;const p=activeProduct;$('#product-drawer').dataset.mode='product';$('#product-drawer').dataset.editIndex=editIndex===null?'':editIndex;$('#product-drawer').innerHTML=`<div class="drawer-head"><span class="eyebrow ink">Customize</span><button class="icon-button" data-close aria-label="Close">×</button></div><div class="product-detail-image">${photo(p)}</div><div class="product-detail-body"><div class="product-detail-title"><h2 id="product-title">${p.name}</h2><strong>${money(p.price)}</strong></div><p class="product-description">${p.desc}</p><div class="nutrition-panel"><div><small>Energy</small><b>${p.calories} kcal</b></div><div><small>Protein</small><b>${p.nutrition.protein}g</b></div><div><small>Carbs</small><b>${p.nutrition.carbs}g</b></div><div><small>Fat</small><b>${p.nutrition.fat}g</b></div></div><p class="nutrition-note">Approximate values per standard serving.</p>${allergenNotice(p)}${p.drink?drinkOptions(p):foodOptions(p)}<div class="quantity-row"><b>Quantity</b><div class="stepper"><button data-qty="minus" aria-label="Decrease quantity">−</button><span id="product-qty">${productQty}</span><button data-qty="plus" aria-label="Increase quantity">+</button></div></div></div><div class="drawer-cta"><button class="button button-dark" id="add-product">${editIndex===null?'Add to order':'Update item'} · <span id="add-price">${money(p.price*productQty)}</span></button></div>`;if(editIndex!==null)restoreProductOptions(cart[editIndex]);updateProductPrice();closePanels();openPanel('#product-drawer')}
function selectedConfig(){return $$('#product-drawer input').filter(input=>input.matches('[data-config]')||input.checked).map(input=>input.value)}
function selectedChoices(){const choices={};$$('#product-drawer input').filter(input=>input.matches('[data-config]')||input.checked).forEach(input=>(choices[input.name]??=[]).push(input.value));return choices}
function configuredPrice(){return activeProduct.price+$$('#product-drawer input:checked').reduce((s,i)=>s+Number(i.dataset.add||0),0)}
function updateProductPrice(){if(activeProduct)$('#add-price').textContent=money(configuredPrice()*productQty)}
function addCurrentProduct(){const edit=$('#product-drawer').dataset.editIndex,item={id:activeProduct.id,name:activeProduct.name,image:activeProduct.image,size:activeProduct.size,pos:activeProduct.pos,config:selectedConfig(),choices:selectedChoices(),unitPrice:configuredPrice(),qty:productQty};if(edit!=='')cart[Number(edit)]=item;else cart.push(item);updateCart();closePanels();toast(edit!==''?'Item updated':'Added to your order')}
function comboOptions(name,title,items){return `<div class="option-group"><div class="option-label"><h3>${title}</h3><small>Choose one</small></div><div class="segmented">${items.map((item,i)=>`<div class="choice"><input type="radio" id="${name}-${i}" name="${name}" value="${item.label}" data-combo-option data-add="${item.add||0}" ${i===0?'checked':''}><label for="${name}-${i}">${item.label}${item.add?`<small>+${money(item.add)}</small>`:''}</label></div>`).join('')}</div></div>`}
function comboDrinkOptions(p){const serveDefault=fixedServe[p.id]||(p.category==='Iced Coffee'?'Iced':'Hot'),serve=p.id==='date-latte'?comboOptions('combo-serve','Drink temperature',[{label:'Hot'},{label:'Iced'}]):`<div class="combo-fixed-choice"><span>Drink temperature</span><b>${serveDefault}</b><input type="hidden" name="combo-serve" value="${serveDefault}" data-combo-config></div>`,milk=milkDrinkIds.has(p.id)?comboOptions('combo-milk','Milk',[{label:'Whole milk'},{label:'Oat',add:.25},{label:'Almond',add:.25}]):'',sweetChoices=sweetDrinkIds.has(p.id)?[{label:'Regular sweetness'},{label:'Less sweet'},{label:'No sweetener'}]:[{label:'No sweetener'},{label:'Lightly sweetened'},{label:'Regular sweetness'}],sweetness=comboOptions('combo-sweetness','Sweetness',sweetChoices),extra=coffeeDrinkIds.has(p.id)?`<div class="option-group"><div class="option-label"><h3>Drink extras</h3><small>Optional</small></div><div class="check-list"><div class="check-row"><label><input type="checkbox" name="combo-extra" value="Extra espresso shot" data-combo-option data-add=".45"> Extra espresso shot</label><span>+0.45 KD</span></div></div></div>`:'';return `${comboOptions('combo-size','Drink size',[{label:'Regular'},{label:'Large',add:.35}])}${serve}${milk}${sweetness}${extra}`}
function comboFoodOptions(p){const prep=comboOptions('combo-food-prep','Food preparation',[{label:'Warm'},{label:'As is'}]),finish=p.id==='halloumi-focaccia'?comboOptions('combo-food-finish','Sandwich finish',[{label:'As made'},{label:'No tomato relish'},{label:'No rocket'}]):p.id==='labneh-croissant'?comboOptions('combo-food-finish','Croissant finish',[{label:'As made'},{label:'Light zaatar'}]):'';return `${prep}${finish}`}
function selectedComboChoices(){const choices={};$$('#product-drawer input').filter(input=>input.matches('[data-combo-config]')||input.matches('[data-combo-option]:checked')).forEach(input=>(choices[input.name]??=[]).push(input.value));return choices}
function selectedComboConfig(){return Object.values(selectedComboChoices()).flat()}
function configuredComboPrice(){return activeCombo.price+$$('#product-drawer input[data-combo-option]:checked').reduce((sum,input)=>sum+Number(input.dataset.add||0),0)}
function restoreComboOptions(item){if(!item.choices)return;$$('#product-drawer input').forEach(input=>{const saved=item.choices[input.name]||[];if(input.type==='radio'||input.type==='checkbox')input.checked=saved.includes(input.value)})}
function updateComboPrice(){if(activeCombo&&$('#combo-add-price'))$('#combo-add-price').textContent=money(configuredComboPrice()*comboQty)}
function openCombo(id,editIndex=null){activeCombo=combos.find(c=>c.id===id);activeProduct=null;comboQty=editIndex!==null?cart[editIndex].qty:1;const c=activeCombo,drink=products.find(p=>p.id===c.items[0]),food=products.find(p=>p.id===c.items[1]),drawer=$('#product-drawer');drawer.dataset.mode='combo';drawer.dataset.editIndex=editIndex===null?'':editIndex;drawer.innerHTML=`<div class="drawer-head"><span class="eyebrow ink">Customize combo</span><button class="icon-button" data-close aria-label="Close">×</button></div><div class="product-detail-image combo-detail-image"><img src="${c.image}" alt="${esc(c.desc)} together on a café table"></div><div class="product-detail-body"><div class="product-detail-title"><h2 id="product-title">${c.name}</h2><strong>${money(c.price)}</strong></div><p class="product-description">${c.desc}</p><div class="combo-included"><div><small>Drink</small><b>${drink.name}</b></div><div><small>Food</small><b>${food.name}</b></div></div><div class="combo-option-heading"><span>01</span><div><b>Make the drink yours</b><small>Choose the temperature, sweetness and milk that suit you.</small></div></div>${comboDrinkOptions(drink)}<div class="combo-option-heading"><span>02</span><div><b>How would you like the food?</b><small>We will prepare it with the rest of your order.</small></div></div>${comboFoodOptions(food)}<div class="quantity-row"><b>Quantity</b><div class="stepper"><button data-combo-qty="minus" aria-label="Decrease combo quantity">−</button><span id="combo-qty">${comboQty}</span><button data-combo-qty="plus" aria-label="Increase combo quantity">+</button></div></div></div><div class="drawer-cta"><button class="button button-dark" id="add-combo-to-order">${editIndex===null?'Add combo to order':'Update combo'} · <span id="combo-add-price">${money(c.price*comboQty)}</span></button></div>`;if(editIndex!==null)restoreComboOptions(cart[editIndex]);updateComboPrice();closePanels();openPanel('#product-drawer')}
function addCurrentCombo(){const edit=$('#product-drawer').dataset.editIndex,c=activeCombo,item={id:`combo-${c.id}`,comboId:c.id,name:c.name,image:c.image,size:'cover',pos:'center',config:[c.desc,...selectedComboConfig()],choices:selectedComboChoices(),unitPrice:configuredComboPrice(),qty:comboQty,combo:true};if(edit!=='')cart[Number(edit)]=item;else cart.push(item);updateCart();closePanels();toast(edit!==''?'Combo updated':`${c.name} added · You saved ${money(c.regular-c.price)}`)}
function openCart(){renderCart();closePanels();openPanel('#cart-drawer')}
function renderCart(){const content=cart.length?`<div class="cart-body">${cart.map((i,index)=>`<article class="cart-item">${photo(i,'cart-thumb','')}<div><h3>${i.qty}× ${i.name}</h3><p>${i.config.join(' · ')}</p><div class="cart-item-actions">${i.combo?`<button class="link-button" data-edit-combo="${index}">Edit combo</button>`:`<button class="link-button" data-edit-item="${index}">Edit</button>`}<button class="link-button" data-remove-item="${index}">Remove</button></div></div><div class="cart-item-price">${money(i.unitPrice*i.qty)}</div></article>`).join('')}</div><div class="cart-summary"><div class="summary-row"><span>Subtotal</span><span>${money(total())}</span></div><div class="summary-row"><span>Pickup service fee</span><span>0.20 KD</span></div><div class="summary-row total"><span>Total</span><span>${money(total()+.2)}</span></div><button class="button button-dark" id="checkout-button">Continue to pickup · ${money(total()+.2)}</button><small class="cart-account-note">${customer?`Signed in as ${esc(customer.name)}`:'You’ll sign in before checkout.'}</small></div>`:`<div class="cart-body cart-empty"><div class="cart-empty-icon">☕</div><h3>Your order is waiting.</h3><p>Add a drink, something to eat, or both.</p><a class="button button-dark" href="#menu" data-close>Browse menu</a></div>`;$('#cart-drawer').innerHTML=`<div class="drawer-head"><h2 id="cart-title">Your order <small>(${cart.reduce((s,i)=>s+i.qty,0)})</small></h2><button class="icon-button" data-close aria-label="Close">×</button></div>${content}`}
function accountForm(){if(authMode==='create')return `<div class="account-auth"><p class="eyebrow ink">Create account</p><h2 id="account-title">Keep every order in one place.</h2><p>Save your details and follow each pickup from confirmed to ready.</p><form id="create-account-form" novalidate><div class="field"><label for="account-name">Full name</label><input id="account-name" name="name" autocomplete="name" required placeholder="Your name"><small data-auth-error="name"></small></div><div class="field"><label for="account-email">Email</label><input id="account-email" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><small data-auth-error="email"></small></div><div class="field"><label for="account-phone">Mobile number</label><input id="account-phone" name="phone" type="tel" autocomplete="tel" required placeholder="+965 5000 0000"><small data-auth-error="phone"></small></div><div class="field"><label for="account-password">Password</label><input id="account-password" name="password" type="password" autocomplete="new-password" required placeholder="8 or more characters"><small data-auth-error="password"></small></div><button class="button button-dark" type="submit">Create account</button></form><p class="auth-switch">Already have an account? <button data-auth-mode="signin">Sign in</button></p><p class="demo-note">Portfolio demo: your profile and orders stay only in this browser. Passwords are never stored.</p></div>`;return `<div class="account-auth"><p class="eyebrow ink">Welcome back</p><h2 id="account-title">Sign in to continue.</h2><p>See your current pickup, previous orders and saved contact details.</p><form id="signin-form" novalidate><div class="field"><label for="signin-email">Email</label><input id="signin-email" name="email" type="email" autocomplete="email" required value="${esc(storedAccount?.email||'')}" placeholder="you@example.com"><small data-auth-error="email"></small></div><div class="field"><label for="signin-password">Password</label><input id="signin-password" name="password" type="password" autocomplete="current-password" required placeholder="Your password"><small data-auth-error="password"></small></div><button class="button button-dark" type="submit">Sign in</button></form><p class="auth-switch">New to Sukun? <button data-auth-mode="create">Create an account</button></p><p class="demo-note">Portfolio demo: use any valid email and a password of 8+ characters. Nothing is sent or stored as a password.</p></div>`}
function getOrderStatus(order){const seconds=(Date.now()-order.createdAt)/1000,index=seconds<12?0:seconds<45?1:2;return {index,label:['Order confirmed','In preparation','Ready for pickup'][index],message:['We sent your order to the selected café.','The bar team is making your order now.','Your order is ready at the pickup counter.'][index]}}
function isActiveOrder(order){return Date.now()-order.createdAt<75000}
function statusTimeline(order){const status=getOrderStatus(order);return `<div class="status-timeline" aria-label="Order status">${['Confirmed','In preparation','Ready'].map((s,i)=>`<div class="status-step ${i<=status.index?'is-complete':''} ${i===status.index?'is-current':''}"><span>${i<status.index?'✓':i+1}</span><small>${s}</small></div>`).join('')}</div>`}
function formatDate(ts){return new Intl.DateTimeFormat(currentLanguage==='ar'?'ar-KW':'en-KW',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(ts))}
function pickupSubLabel(order){return order.timeChoice===order.readyLabel?'Selected pickup time':order.timeChoice}
function orderCard(order){const branch=locations.find(l=>l.id===order.branchId),status=getOrderStatus(order);return `<article class="order-card"><div class="order-card-top"><div><span class="order-number">${order.number}</span><small>${formatDate(order.createdAt)}</small></div><span class="status-pill status-${status.index}">${status.label}</span></div>${statusTimeline(order)}<p class="status-message">${status.message}</p><div class="order-facts"><div><small>Pickup</small><b>${branch.name}</b><span>${branch.area}</span></div><div><small>Expected</small><b>${order.readyLabel}</b><span>${pickupSubLabel(order)}</span></div></div><details><summary>Order details · ${money(order.paid)}</summary><ul>${order.items.map(i=>`<li><span>${i.qty}× ${i.name}</span><b>${money(i.unitPrice*i.qty)}</b></li>`).join('')}</ul></details><a class="text-link" href="${branch.map}" target="_blank" rel="noopener">Directions to pickup ↗</a></article>`}
function completedOrderCard(order){const branch=locations.find(l=>l.id===order.branchId),itemCount=order.items.reduce((sum,item)=>sum+item.qty,0);return `<details class="history-order"><summary><div class="history-order-main"><span class="order-number">${order.number}</span><small>${formatDate(order.createdAt)} · ${branch.name}</small></div><div class="history-order-total"><b>${money(order.paid)}</b><span class="status-pill status-completed">Completed</span></div></summary><div class="history-order-body"><div class="history-order-meta"><span><small>Pickup location</small><b>${branch.name}</b></span><span><small>Items</small><b>${itemCount}</b></span></div><ul>${order.items.map(i=>`<li><span>${i.qty}× ${i.name}</span><b>${money(i.unitPrice*i.qty)}</b></li>`).join('')}</ul></div></details>`}
function renderAccount(mode=authMode){
  authMode=mode;
  const drawer=$('#account-drawer');
  if(!customer){drawer.innerHTML=`<div class="drawer-head"><span>Customer account</span><button class="icon-button" data-close aria-label="Close">×</button></div><div class="account-body">${accountForm()}</div>`;return}
  const accountOrders=orders.filter(order=>order.customerEmail===customer.email.toLowerCase()),activeOrders=accountOrders.filter(isActiveOrder),historyOrders=accountOrders.filter(order=>!isActiveOrder(order));
  const currentView=`<section class="account-order-section"><div class="account-heading"><div><p class="eyebrow ink">Current order</p><h2>${activeOrders.length?`${activeOrders.length} active`:'Nothing in progress'}</h2></div>${activeOrders.length?'<button class="refresh-status" data-refresh-orders>Refresh status</button>':''}</div>${activeOrders.length?`<p class="demo-note">Your live pickup status updates here from confirmed to ready.</p><div class="orders-list">${activeOrders.map(orderCard).join('')}</div>`:`<p class="account-section-empty">You don’t have an active pickup right now.</p>`}</section>`;
  const historyView=`<details class="history-disclosure"><summary><div><b>Order history</b><small>${historyOrders.length?`${historyOrders.length} completed`:'No past orders'}</small></div><span class="history-chevron" aria-hidden="true">⌄</span></summary><div class="history-list">${historyOrders.length?historyOrders.map(completedOrderCard).join(''):`<div class="account-empty"><p>Your completed pickups will appear here.</p>${accountOrders.length?'':'<a class="button button-dark" href="#menu" data-close>Browse the menu</a>'}</div>`}</div></details>`;
  drawer.innerHTML=`<div class="drawer-head"><h2 id="account-title">My account</h2><button class="icon-button" data-close aria-label="Close">×</button></div><div class="account-body"><div class="account-identity"><span class="account-avatar large">${customer.name.charAt(0).toUpperCase()}</span><div><h3>${esc(customer.name)}</h3><p>${esc(customer.email)}${customer.phone?` · ${esc(customer.phone)}`:''}</p></div><button class="link-button" data-sign-out>Sign out</button></div>${currentView}${historyView}</div>`
}
function openAccount(mode='signin'){authMode=mode;closePanels();renderAccount(mode);openPanel('#account-drawer')}
function saveCustomer(next){customer=next;storedAccount=next;orders=orders.map(order=>order.customerEmail?order:{...order,customerEmail:next.email.toLowerCase()});localStorage.setItem('sukun-orders',JSON.stringify(orders));localStorage.setItem('sukun-account',JSON.stringify(next));localStorage.setItem('sukun-signed-in','true');syncAccountUI()}
function finishAuth(next){saveCustomer(next);const branch=pendingCheckoutBranch;pendingCheckoutBranch=null;if(branch){closePanels();checkout(branch)}else{renderAccount();toast(`Welcome, ${next.name.split(' ')[0]}`)}}
function validateAuth(form,creating){const data=new FormData(form),email=(data.get('email')||'').trim(),password=(data.get('password')||''),name=(data.get('name')||'').trim(),phone=(data.get('phone')||'').trim();$$('[data-auth-error]').forEach(el=>el.textContent='');let ok=true;if(!/^\S+@\S+\.\S+$/.test(email)){$('[data-auth-error="email"]').textContent='Enter a valid email.';ok=false}if(password.length<8){$('[data-auth-error="password"]').textContent='Use at least 8 characters.';ok=false}if(creating&&name.length<2){$('[data-auth-error="name"]').textContent='Enter your full name.';ok=false}if(creating&&!/^[+\d][\d\s-]{6,}$/.test(phone)){$('[data-auth-error="phone"]').textContent='Enter a valid mobile number.';ok=false}if(!ok)return;if(creating)finishAuth({name,email,phone});else{const inferredName=email.split('@')[0].replace(/[._-]+/g,' ').replace(/\b\w/g,letter=>letter.toUpperCase()),match=storedAccount&&storedAccount.email.toLowerCase()===email.toLowerCase()?storedAccount:{name:inferredName,email,phone:''};finishAuth(match)}}
function checkout(branchId='shuwaikh'){if(!cart.length){toast('Add something to your order first');return}if(!customer){pendingCheckoutBranch=branchId;openAccount('signin');toast('Sign in to continue to checkout');return}closePanels();checkoutStep=1;const modal=$('#checkout-modal');modal.dataset.branch=branchId;modal.dataset.time='As soon as possible';$('#overlay').hidden=false;modal.hidden=false;document.body.classList.add('is-locked');renderCheckout()}
function renderCheckout(){const modal=$('#checkout-modal');if(checkoutStep===4){renderConfirmation();return}modal.innerHTML=`<div class="checkout-shell"><div class="checkout-main"><div class="checkout-top"><a class="brand" href="#home" aria-label="Sukun Café home"><span class="brand-copy"><span class="brand-name sukun-wordmark" aria-hidden="true"><span>S</span><span>U</span><span>K</span><span class="marked-u">U</span><span>N</span></span><span class="brand-sub">CAFÉ</span></span></a><span class="checkout-account">Ordering as ${esc(customer.name)}</span><button class="icon-button" data-close-checkout aria-label="Close checkout">×</button></div><div class="progress-labels"><span class="${checkoutStep>=1?'is-active':''}">Pickup</span><span class="${checkoutStep>=2?'is-active':''}">Time</span><span class="${checkoutStep>=3?'is-active':''}">Review</span></div><div class="progress-steps" aria-label="Checkout progress"><span class="is-active"></span><span class="${checkoutStep>=2?'is-active':''}"></span><span class="${checkoutStep>=3?'is-active':''}"></span></div>${checkoutStepContent()}</div><aside class="checkout-side">${orderSummary()}</aside></div>`}
function checkoutStepContent(){const branch=$('#checkout-modal').dataset.branch||'shuwaikh',time=$('#checkout-modal').dataset.time||'As soon as possible';if(checkoutStep===1)return `<section class="checkout-step"><p class="eyebrow ink">Step 1 of 3</p><h3 id="checkout-title">Choose your pickup café.</h3><p>Ready-time estimates update with your selected branch.</p><div class="select-cards">${locations.map(l=>`<div class="select-card"><input type="radio" name="branch" id="branch-${l.id}" value="${l.id}" ${branch===l.id?'checked':''}><label for="branch-${l.id}"><span><b>${l.name}</b><small>${l.area}</small></span><span class="pickup-available">${l.ready}</span></label></div>`).join('')}</div><div class="checkout-actions"><button class="button button-outline" data-back-cart>Back to cart</button><button class="button button-dark" data-checkout-next>Choose a time →</button></div></section>`;if(checkoutStep===2)return `<section class="checkout-step"><p class="eyebrow ink">Step 2 of 3</p><h3 id="checkout-title">When will you arrive?</h3><p>We’ll keep the selected timing visible through confirmation and order status.</p><div class="time-grid">${['As soon as possible','In 20 minutes','In 30 minutes','10:30 am','10:45 am','11:00 am'].map((t,i)=>`<div class="choice"><input type="radio" name="time" id="time-${i}" value="${t}" ${time===t?'checked':''}><label for="time-${i}">${t}</label></div>`).join('')}</div><div class="checkout-actions"><button class="button button-outline" data-checkout-back>← Back</button><button class="button button-dark" data-checkout-next>Review details →</button></div></section>`;return `<section class="checkout-step"><p class="eyebrow ink">Step 3 of 3</p><h3 id="checkout-title">Review and place your order.</h3><p>We’ll use these details for pickup updates and your receipt.</p><form id="checkout-form" novalidate><div class="form-grid"><div class="field full"><label for="customer-name">Full name</label><input id="customer-name" name="name" autocomplete="name" required value="${esc(customer.name)}"><small data-error="name"></small></div><div class="field"><label for="phone">Mobile number</label><input id="phone" name="phone" type="tel" autocomplete="tel" required value="${esc(customer.phone||'')}" placeholder="+965 5000 0000"><small data-error="phone"></small></div><div class="field"><label for="email">Email receipt</label><input id="email" name="email" type="email" autocomplete="email" required value="${esc(customer.email)}"><small data-error="email"></small></div></div><div class="payment-options"><div class="select-card"><input type="radio" name="payment" id="knet" value="KNET" checked><label for="knet"><b>KNET</b><span>KD</span></label></div><div class="select-card"><input type="radio" name="payment" id="applepay" value="Apple Pay"><label for="applepay"><b>Apple Pay</b><span></span></label></div><div class="select-card"><input type="radio" name="payment" id="cardpay" value="Card"><label for="cardpay"><b>Credit / debit card</b><span>••••</span></label></div></div><p class="payment-note">Demo checkout — your payment choice is saved, but no charge is made.</p><div class="checkout-actions"><button type="button" class="button button-outline" data-checkout-back>← Back</button><button type="submit" class="button button-dark">Place order · ${money(total()+.2)}</button></div></form></section>`}
function orderSummary(){const branch=locations.find(l=>l.id===($('#checkout-modal').dataset.branch||'shuwaikh'));return `<div class="checkout-order"><h3>Your pickup</h3><div class="select-card"><label><span><b>${branch.name}</b><small>${branch.area}</small></span></label></div><p><b>${$('#checkout-modal').dataset.time||'As soon as possible'}</b></p><hr>${cart.map(i=>`<div class="mini-order">${photo(i,'mini-thumb','')}<div><b>${i.qty}× ${i.name}</b><small>${i.config.slice(0,2).join(' · ')}</small></div><span>${money(i.qty*i.unitPrice)}</span></div>`).join('')}<div class="summary-row"><span>Subtotal</span><span>${money(total())}</span></div><div class="summary-row"><span>Pickup service fee</span><span>0.20 KD</span></div><div class="summary-row total"><span>Total</span><span>${money(total()+.2)}</span></div></div>`}
function validateAndConfirm(form){const data=new FormData(form),name=(data.get('name')||'').trim(),phone=(data.get('phone')||'').trim(),email=(data.get('email')||'').trim(),payment=data.get('payment')||'KNET';let ok=true;$$('[data-error]').forEach(e=>e.textContent='');if(name.length<2){$('[data-error="name"]').textContent='Please enter your name.';ok=false}if(!/^[+\d][\d\s-]{6,}$/.test(phone)){$('[data-error="phone"]').textContent='Enter a valid mobile number.';ok=false}if(!/^\S+@\S+\.\S+$/.test(email)){$('[data-error="email"]').textContent='Enter a valid email.';ok=false}if(!ok)return;saveCustomer({name,email,phone});const branch=locations.find(l=>l.id===$('#checkout-modal').dataset.branch),timeChoice=$('#checkout-modal').dataset.time,paid=total()+.2;lastOrder={number:`SK${Math.floor(1000+Math.random()*8999)}`,createdAt:Date.now(),branchId:branch.id,timeChoice,readyLabel:timeChoice==='As soon as possible'?branch.ready:timeChoice,payment,paid,customerEmail:email.toLowerCase(),items:cart.map(i=>({...i}))};orders=[lastOrder,...orders];localStorage.setItem('sukun-orders',JSON.stringify(orders));cart=[];updateCart();checkoutStep=4;renderCheckout()}
function renderConfirmation(){const order=lastOrder||orders[0],branch=locations.find(l=>l.id===order.branchId),status=getOrderStatus(order);$('#checkout-modal').innerHTML=`<section class="confirmation"><div class="confirmation-card"><div class="success-mark">✓</div><h2 id="checkout-title">Order confirmed.</h2><p>${status.message} You can follow every update from My account.</p><span class="order-number">${order.number}</span>${statusTimeline(order)}<div class="confirmation-grid"><div><small>Pickup from</small><b>${branch.name}</b><span>${branch.area}</span></div><div><small>Expected ready</small><b>${order.readyLabel}</b><span>${pickupSubLabel(order)}</span></div><div><small>Payment choice</small><b>${order.payment}</b><span>Demo only · no charge made</span></div><div><small>Pickup instructions</small><b>Show ${order.number} at the counter</b><a href="${branch.map}" target="_blank" rel="noopener">Directions ↗</a></div></div><div class="confirmation-actions"><button class="button button-dark" data-view-orders>View order status</button><button class="button button-outline" data-done>Back to home</button></div></div></section>`}
function closeCheckout(){$('#checkout-modal').hidden=true;$('#overlay').hidden=true;document.body.classList.remove('is-locked');$('#checkout-modal').dataset.branch='';$('#checkout-modal').dataset.time=''}
function quickConfig(p){if(!p.drink)return ['Warm'];const config=[p.id==='espresso'?'Double':'Regular',fixedServe[p.id]||(p.category==='Iced Coffee'?'Iced':'Hot')];if(milkDrinkIds.has(p.id))config.push('Whole milk');if(sweetDrinkIds.has(p.id))config.push('Regular');return config}
document.addEventListener('click',e=>{const languageButton=e.target.closest('[data-language-toggle]');if(languageButton){setLanguage(currentLanguage==='en'?'ar':'en');closeMobileMenu();return}if(e.target.closest('.mobile-menu-panel a,.mobile-menu-panel button'))closeMobileMenu();const scrollLink=e.target.closest('[data-scroll]');if(scrollLink){e.preventDefault();document.getElementById(scrollLink.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return}const product=e.target.closest('[data-product]');if(product&&!e.target.closest('[data-quick-add]'))openProduct(product.dataset.product);const quick=e.target.closest('[data-quick-add]');if(quick){e.stopPropagation();const p=products.find(x=>x.id===quick.dataset.quickAdd);cart.push({id:p.id,name:p.name,image:p.image,size:p.size,pos:p.pos,config:quickConfig(p),unitPrice:p.price,qty:1});updateCart();toast(`${p.name} added`)}const combo=e.target.closest('[data-add-combo]');if(combo)openCombo(combo.dataset.addCombo);if(e.target.closest('[data-open-cart]'))openCart();if(e.target.closest('[data-open-account]'))openAccount();if(e.target.closest('[data-close]'))closePanels();if(e.target===$('#overlay')){closePanels();closeCheckout()}const mode=e.target.closest('[data-auth-mode]');if(mode)renderAccount(mode.dataset.authMode);if(e.target.closest('[data-sign-out]')){customer=null;localStorage.setItem('sukun-signed-in','false');syncAccountUI();renderAccount('signin');toast('Signed out')}if(e.target.closest('[data-refresh-orders]'))renderAccount();const cat=e.target.closest('[data-category]');if(cat){activeCategory=cat.dataset.category;renderMenu()}const branch=e.target.closest('[data-order-branch]');if(branch)checkout(branch.dataset.orderBranch);const qty=e.target.closest('[data-qty]');if(qty){productQty=Math.max(1,productQty+(qty.dataset.qty==='plus'?1:-1));$('#product-qty').textContent=productQty;updateProductPrice()}const comboQtyButton=e.target.closest('[data-combo-qty]');if(comboQtyButton){comboQty=Math.max(1,comboQty+(comboQtyButton.dataset.comboQty==='plus'?1:-1));$('#combo-qty').textContent=comboQty;updateComboPrice()}if(e.target.closest('#add-product'))addCurrentProduct();if(e.target.closest('#add-combo-to-order'))addCurrentCombo();const remove=e.target.closest('[data-remove-item]');if(remove){cart.splice(Number(remove.dataset.removeItem),1);updateCart();renderCart()}const edit=e.target.closest('[data-edit-item]');if(edit){const i=Number(edit.dataset.editItem);openProduct(cart[i].id,i)}const comboEdit=e.target.closest('[data-edit-combo]');if(comboEdit){const i=Number(comboEdit.dataset.editCombo),item=cart[i];openCombo(item.comboId||item.id.replace('combo-',''),i)}if(e.target.closest('#checkout-button'))checkout();if(e.target.closest('[data-back-cart]')){closeCheckout();openCart()}if(e.target.closest('[data-checkout-next]')){const selected=$('#checkout-modal input[type=radio]:checked');if(checkoutStep===1)$('#checkout-modal').dataset.branch=selected.value;if(checkoutStep===2)$('#checkout-modal').dataset.time=selected.value;checkoutStep++;renderCheckout()}if(e.target.closest('[data-checkout-back]')){checkoutStep--;renderCheckout()}if(e.target.closest('[data-close-checkout]'))closeCheckout();if(e.target.closest('[data-view-orders]')){closeCheckout();openAccount()}if(e.target.closest('[data-done]')){closeCheckout();location.hash='home'}if(e.target.closest('#clear-filters')){activeCategory='All';vegOnly=false;searchTerm='';$('#menu-search').value='';renderMenu()}const link=e.target.closest('[data-category-link]');if(link){activeCategory=link.dataset.categoryLink;renderMenu()}});
document.addEventListener('change',e=>{if(e.target.id==='category-filter'){activeCategory=e.target.value;renderMenu()}if(e.target.closest('#product-drawer')){$('#product-drawer').dataset.mode==='combo'?updateComboPrice():updateProductPrice()}if(e.target.name==='branch')$('#checkout-modal').dataset.branch=e.target.value;if(e.target.name==='time')$('#checkout-modal').dataset.time=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id==='checkout-form'){e.preventDefault();validateAndConfirm(e.target)}if(e.target.id==='signin-form'){e.preventDefault();validateAuth(e.target,false)}if(e.target.id==='create-account-form'){e.preventDefault();validateAuth(e.target,true)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMobileMenu();closePanels();closeCheckout()}const card=e.target.closest('[data-product]');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openProduct(card.dataset.product)}});
$('#menu-search').addEventListener('input',e=>{searchTerm=e.target.value;renderMenu()});$('#veg-filter').addEventListener('click',()=>{vegOnly=!vegOnly;renderMenu()});window.addEventListener('hashchange',route);setInterval(()=>{if(customer&&$('#account-drawer').classList.contains('is-open')&&!$('#account-drawer .history-disclosure[open]'))renderAccount()},10000);
renderFeatured();renderCombos();renderLocations();renderMenu();updateCart();syncAccountUI();route();setLanguage(currentLanguage);
const languageObserver=new MutationObserver(mutations=>mutations.forEach(mutation=>mutation.addedNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE||node.nodeType===Node.ELEMENT_NODE)localizeTree(node)})));
languageObserver.observe(document.body,{childList:true,subtree:true});
